CREATE OR REPLACE FUNCTION calculate_spread_rate(p_best_ask real, p_best_bid real, p_mid_price real)
RETURNS real AS $$
BEGIN
  RETURN ((p_best_ask - p_best_bid) / p_mid_price) * 100;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_spread_rate(p_best_ask real, p_best_bid real, p_mid_price real)
RETURNS real AS $$
BEGIN
  RETURN ((p_best_ask - p_best_bid) / p_mid_price) * 100;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_spread_rate(p_market_data jsonb)
RETURNS real AS $$
BEGIN
  RETURN ((p_market_data->>'best_ask')::real - (p_market_data->>'best_bid')::real) / (p_market_data->>'mid_price')::real * 100;
END;
$$ LANGUAGE plpgsql;
